      {todo.title}
      {done ? ' (done)' : null}{' '}
      <button type="button" onClick={complete}>
        Complete
      </button>
      {feedback === 'already-completed' ? (
        <ErrorMessage>This todo is already completed.</ErrorMessage>
      ) : null}
      {feedback === 'failed' ? <ErrorMessage>The todo could not be completed.</ErrorMessage> : null}
    </li>
  )
}
