import { useState } from 'react'

import { ErrorMessage } from '../../../shared/ui/ErrorMessage/ErrorMessage'
import type { TodoViewModel } from '../../application/TodoViewModel'
import { useTodosUseCases } from '../useTodosUseCases/useTodosUseCases'

type TodoItemProps = {
  todo: TodoViewModel
}

type Feedback = 'already-completed' | 'failed' | null

export const TodoItem = ({ todo }: TodoItemProps) => {
  const { completeTodo } = useTodosUseCases()
  const [done, setDone] = useState(todo.status === 'done')
  const [feedback, setFeedback] = useState<Feedback>(null)

  const complete = async () => {
    setFeedback(null)
    try {
      const result = await completeTodo.execute(todo.id)
      setDone(true)
      if (result === 'already-completed') setFeedback('already-completed')
    } catch {
      setFeedback('failed')
    }
  }

  return (
    <li>
      {todo.title}
      {done ? ' (done)' : null}{' '}
      <button type="button" onClick={complete}>
        Complete
      </button>
      {feedback === 'already-completed' ? (
        <ErrorMessage>This todo is already completed.</ErrorMessage>
      ) : null}
      {feedback === 'failed' ? <ErrorMessage>The todo could not be completed.</ErrorMessage> : null}
    </li>
  )
}
